import fs from 'node:fs/promises';
import path from 'node:path';

const KEY = /^[a-z][a-z0-9_-]*$/;

function invalid() {
  return Object.assign(new Error('Invalid batch'), { code: 'ERR_INVALID_BATCH' });
}

function corrupt(file) {
  return Object.assign(new Error(`Corrupt ledger file: ${file}`), { code: 'ERR_LEDGER_CORRUPT' });
}

function conflict() {
  return Object.assign(new Error('Batch ID already used'), { code: 'ERR_BATCH_CONFLICT' });
}

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

// Returns a normalized copy ({id, entries: [{key, delta}]}) or null if the shape is invalid.
// -0 is normalized to 0 so in-memory results match what JSON round-trips to.
function normalize(batch) {
  if (!isRecord(batch) || typeof batch.id !== 'string' || !batch.id || !Array.isArray(batch.entries)) return null;
  const entries = [];
  for (let i = 0; i < batch.entries.length; i++) {
    const entry = batch.entries[i];
    if (!isRecord(entry) || typeof entry.key !== 'string' || !KEY.test(entry.key) || !Number.isSafeInteger(entry.delta)) return null;
    entries.push({ key: entry.key, delta: entry.delta + 0 });
  }
  return { id: batch.id, entries };
}

function sameEntries(a, b) {
  return a.length === b.length && a.every((entry, i) => entry.key === b[i].key && entry.delta === b[i].delta);
}

function emptyLedger() {
  return { revision: 0, balances: {}, receipts: [] };
}

function checkLedger(state, file) {
  if (!isRecord(state) || !Number.isSafeInteger(state.revision) || !isRecord(state.balances) || !Array.isArray(state.receipts)) throw corrupt(file);
  if (state.revision !== state.receipts.length) throw corrupt(file);
  for (const [key, value] of Object.entries(state.balances)) {
    if (!KEY.test(key) || !Number.isSafeInteger(value)) throw corrupt(file);
  }
  const receipts = state.receipts.map(receipt => normalize(receipt));
  if (receipts.some(receipt => !receipt)) throw corrupt(file);
  return { revision: state.revision, balances: { ...state.balances }, receipts };
}

function checkPending(pending, file) {
  const batch = isRecord(pending) ? normalize(pending.batch) : null;
  if (!batch || !Number.isSafeInteger(pending.base) || pending.base < 0) throw corrupt(file);
  return { base: pending.base, batch };
}

async function read(io, file) {
  let text;
  try { text = await io.readFile(file, 'utf8'); }
  catch (error) { if (error && error.code === 'ENOENT') return undefined; throw error; }
  return JSON.parse(text);
}

// Atomic publish: stage the full content, then rename over the durable name.
async function save(io, directory, name, value) {
  const staged = path.join(directory, `${name}.tmp`);
  await io.writeFile(staged, JSON.stringify(value));
  await io.rename(staged, path.join(directory, `${name}.json`));
}

async function removePending(io, directory) {
  try { await io.unlink(path.join(directory, 'pending.json')); }
  catch (error) { if (!error || error.code !== 'ENOENT') throw error; }
}

// Pure: returns the next snapshot or throws ERR_INVALID_BATCH on unsafe balances.
function apply(state, batch) {
  const balances = { ...state.balances };
  for (const { key, delta } of batch.entries) {
    const value = (Object.hasOwn(balances, key) ? balances[key] : 0) + delta;
    if (!Number.isSafeInteger(value)) throw invalid();
    balances[key] = value;
  }
  return { revision: state.revision + 1, balances, receipts: [...state.receipts, batch] };
}

// Reads durable state without writing. Returns the effective committed snapshot
// plus what remains to finish any pending transaction.
async function load(io, directory) {
  const ledgerFile = path.join(directory, 'ledger.json');
  const pendingFile = path.join(directory, 'pending.json');
  const stored = await read(io, ledgerFile);
  const state = stored === undefined ? emptyLedger() : checkLedger(stored, ledgerFile);
  const raw = await read(io, pendingFile);
  if (raw === undefined) return { state, hasPending: false, publish: false };
  const pending = checkPending(raw, pendingFile);
  const existing = state.receipts.find(receipt => receipt.id === pending.batch.id);
  if (existing) {
    // Already published; only the recovery metadata is left behind.
    if (!sameEntries(existing.entries, pending.batch.entries)) throw corrupt(pendingFile);
    return { state, hasPending: true, publish: false };
  }
  if (state.revision !== pending.base) throw corrupt(pendingFile);
  let next;
  try { next = apply(state, pending.batch); }
  catch { throw corrupt(pendingFile); }
  return { state: next, hasPending: true, publish: true };
}

async function finish(io, directory, loaded) {
  if (loaded.publish) await save(io, directory, 'ledger', loaded.state);
  if (loaded.hasPending) await removePending(io, directory);
  return loaded.state;
}

export async function recoverLedger(directory, { io = fs } = {}) {
  await io.mkdir(directory, { recursive: true });
  return finish(io, directory, await load(io, directory));
}

export async function commitBatch(directory, batch, { io = fs, checkpoint } = {}) {
  batch = normalize(batch);
  if (!batch) throw invalid();
  await io.mkdir(directory, { recursive: true });
  const loaded = await load(io, directory);
  const existing = loaded.state.receipts.find(receipt => receipt.id === batch.id);
  if (existing) {
    await finish(io, directory, loaded);
    if (!sameEntries(existing.entries, batch.entries)) throw conflict();
    return loaded.state;
  }
  // Validate balances before any durable change, including finishing earlier recovery.
  const next = apply(loaded.state, batch);
  await finish(io, directory, loaded);

  await save(io, directory, 'pending', { base: loaded.state.revision, batch });
  if (checkpoint) await checkpoint('prepared');
  await save(io, directory, 'ledger', next);
  if (checkpoint) await checkpoint('published');
  await removePending(io, directory);
  if (checkpoint) await checkpoint('complete');
  return next;
}

import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import assert from 'node:assert/strict';
import { commitBatch, recoverLedger } from './src/ledger.js';

const a = { id: 'a', entries: [{ key: 'cash', delta: 5 }] };
const b = { id: 'b', entries: [{ key: 'cash', delta: 3 }, { key: 'bank', delta: -1 }, { key: 'cash', delta: 1 }] };
const expected = { revision: 2, balances: { cash: 9, bank: -1 }, receipts: [a, b] };
let runs = 0;

async function dir() { return fs.mkdtemp(path.join(os.tmpdir(), 'ledger-smoke-')); }

// Fail the n-th call of `method` (optionally after a partial write).
function faulty(method, n, partial) {
  let count = 0;
  return new Proxy(fs, { get(target, prop) {
    const fn = target[prop];
    if (prop !== method) return fn;
    return async (...args) => {
      if (++count === n) {
        if (partial) await fs.writeFile(args[0], String(args[1]).slice(0, 3));
        throw Object.assign(new Error(`injected ${method}#${n}`), { code: 'EIO' });
      }
      return fn.apply(target, args);
    };
  } });
}

async function finalCheck(d) {
  assert.deepEqual(await recoverLedger(d), expected);
  assert.deepEqual(await recoverLedger(d), expected);
  const names = (await fs.readdir(d)).filter(n => n.endsWith('.json')).sort();
  assert.deepEqual(names, ['ledger.json']);
  assert.deepEqual(await commitBatch(d, b), expected);
  await assert.rejects(commitBatch(d, { id: 'b', entries: [] }), { code: 'ERR_BATCH_CONFLICT' });
  assert.deepEqual(await recoverLedger(d), expected);
  runs++;
}

for (const phase of ['prepared', 'published', 'complete']) {
  for (const retry of ['recover', 'commit']) {
    const d = await dir();
    await commitBatch(d, a);
    const stop = new Error('stop');
    await assert.rejects(commitBatch(d, b, { checkpoint: async p => { if (p === phase) throw stop; } }), e => e === stop);
    if (retry === 'commit') assert.deepEqual(await commitBatch(d, b), expected);
    await finalCheck(d);
  }
}

for (const method of ['writeFile', 'rename', 'unlink']) {
  for (let n = 1; n <= 4; n++) {
    for (const partial of method === 'writeFile' ? [false, true] : [false]) {
      const d = await dir();
      await commitBatch(d, a);
      let failed = false;
      try { await commitBatch(d, b, { io: faulty(method, n, partial) }); } catch (e) { assert.equal(e.code, 'EIO'); failed = true; }
      // Also a failure during recovery of a pending transaction followed by a fresh retry.
      try { await recoverLedger(d, { io: faulty(method, 1, partial) }); } catch (e) { assert.equal(e.code, 'EIO'); }
      assert.deepEqual(await commitBatch(d, b), expected, `${method}#${n} failed=${failed}`);
      await finalCheck(d);
    }
  }
}

// Checkpoint ordering, invalid batches, overflow without durable change, corrupt JSON.
{
  const d = await dir();
  const phases = [];
  await commitBatch(d, { id: 'e', entries: [] }, { checkpoint: async p => { phases.push(p); } });
  assert.deepEqual(phases, ['prepared', 'published', 'complete']);
  await commitBatch(d, { id: 'big', entries: [{ key: 'x', delta: Number.MAX_SAFE_INTEGER }] });
  const before = await fs.readFile(path.join(d, 'ledger.json'), 'utf8');
  await assert.rejects(commitBatch(d, { id: 'o', entries: [{ key: 'x', delta: 1 }] }), { code: 'ERR_INVALID_BATCH' });
  for (const bad of [null, { id: '', entries: [] }, { id: 'q', entries: [{ key: 'A', delta: 1 }] }, { id: 'q', entries: [{ key: 'a', delta: 1.5 }] }, { id: 'q' }])
    await assert.rejects(commitBatch(d, bad), { code: 'ERR_INVALID_BATCH' });
  assert.equal(await fs.readFile(path.join(d, 'ledger.json'), 'utf8'), before);
  await fs.writeFile(path.join(d, 'pending.json'), '{oops');
  await assert.rejects(recoverLedger(d), SyntaxError);
  await fs.writeFile(path.join(d, 'ledger.json'), '{oops');
  await fs.unlink(path.join(d, 'pending.json'));
  await assert.rejects(recoverLedger(d), SyntaxError);
  runs++;
}
console.log('ok', runs);
